package pe.edu.pucp.admitu.seguridad.bo;
import java.time.*;import java.util.*;import pe.edu.pucp.admitu.bo.Validaciones;import pe.edu.pucp.admitu.config.TransactionContext;import pe.edu.pucp.admitu.persona.Postulante;import pe.edu.pucp.admitu.persona.impl.PostulanteImpl;import pe.edu.pucp.admitu.seguridad.*;import pe.edu.pucp.admitu.seguridad.dao.CuentaUsuarioDAO;import pe.edu.pucp.admitu.seguridad.impl.CuentaUsuarioImpl;import pe.edu.pucp.admitu.seguridad.boi.IAutenticacionBO;
public class AutenticacionBOImpl implements IAutenticacionBO {
 private final CuentaUsuarioDAO dao=new CuentaUsuarioImpl();
 public SesionUsuario ingresar(String correo,String clave){if(correo==null||correo.length()>150||clave==null||clave.length()>128)throw new SecurityException("Credenciales incorrectas");CuentaUsuario c=dao.buscarCorreo(correo.trim().toLowerCase(Locale.ROOT));if(c==null){ClaveSegura.verificar(clave,INEXISTENTE);throw new SecurityException("Credenciales incorrectas");}if(!c.activo()||c.bloqueada())throw new SecurityException("Credenciales incorrectas o cuenta temporalmente bloqueada");boolean valido=ClaveSegura.verificar(clave,c.claveHash());dao.intento(c.id(),valido);if(!valido)throw new SecurityException("Credenciales incorrectas");String token=ClaveSegura.token();dao.crearSesion(ClaveSegura.huella(token),c.id());SesionUsuario u=dao.buscarSesion(ClaveSegura.huella(token));if(u==null)throw new SecurityException("Cuenta no disponible");u.setToken(token);return u;}
 private static final String INEXISTENTE="pbkdf2_sha256$600000$AAAAAAAAAAAAAAAAAAAAAA==$AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";
 public int registrar(Postulante p,String clave){if(p==null)throw new IllegalArgumentException("Datos del postulante requeridos");String hash=ClaveSegura.crear(clave);Validaciones.persona(p.getNombres(),p.getApellidoPaterno(),p.getApellidoMaterno(),p.getCorreo(),p.getTipoDocumento(),p.getNumeroDocumento(),p.getTelefono());if(p.getFechaNacimiento()==null||p.getFechaNacimiento().isAfter(LocalDate.now(ZoneId.of("America/Lima"))))throw new IllegalArgumentException("Fecha de nacimiento no válida");if(p.isTieneDiscapacidad()&&(p.getNumeroCarnetConadis()==null||p.getNumeroCarnetConadis().isBlank()))throw new IllegalArgumentException("Indica el carné CONADIS");try{int id=new PostulanteImpl().insertar(p);dao.crearCuenta(id,p.getCorreo(),"postulante",hash);TransactionContext.commit();return id;}catch(Exception e){TransactionContext.rollback();throw e instanceof RuntimeException?(RuntimeException)e:new IllegalStateException(e);}finally{TransactionContext.close();}}
 public SesionUsuario autenticar(String token){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))return null;return dao.buscarSesion(ClaveSegura.huella(token));}
 public void salir(String token){if(token!=null&&token.length()==43)dao.eliminarSesion(ClaveSegura.huella(token));}
 public Set<Integer> idsAutorizados(String recurso,int persona){return dao.ids(recurso,persona);}
}
